import{t as e}from"./utils-COoNfFoj.js";var t={slug:`bojan-radojicic`,influencerName:`Bojan Radojicic`,influencerHandle:`@BojanRadojicic`,influencerAvatarUrl:`${e}/bojan-radojicic-avatar.png`,heroDescription:`“As a financial analyst, I’m constantly working with massive datasets, but spreadsheets alone don’t tell me where the real opportunities or problems are. I built this tool to surface margin leaks, highlight the highest ROI opportunities, and give me real-time visibility into top and low sales performers so I can make smarter strategy and compensation decisions.”`,assetTitle:`Sales Intelligence`,screenshotUrl:`${e}/bojan-radojicic.png`,remixUrl:`https://www.perplexity.ai/computer/a/sales-intelligence-dashboard-3i6pXbimSISg.jMgMLrgcw`,promptTitle:`Try Bojan's prompt`,promptText:`“Using the attached sales database, build me a full-stack web app that turns raw sales data into actionable business intelligence. I need real-time visibility into top and low performers by salesperson, location, product, and customer, including metrics like revenue, gross profit, margins, growth trends, and profitability. The platform should identify the most profitable customers, surface margin leaks and underperforming areas, and generate AI-powered recommendations and action plans across sales, pricing, product mix, locations, and management performance. Make every chart, table, and filter fully interactive using real data from the database. Design the app with a modern, futuristic corporate finance aesthetic — light background, minimal color palette, subtle gradients, clean typography, and high-end dashboard styling.”`};export{t as default};
